  (5119, md5($bt$[{"phase": "education", "start": null, "end": null, "title": "Degree in film and television", "organisation": null, "detail": null, "source": {"title": "politics.co.uk: Natasha Irons", "url": "https://www.politics.co.uk/people/natasha-irons/"}}, {"phase": "career", "start": "2008-02", "end": "2024-07", "title": "Media planning manager", "organisation": "Channel 4 Television", "detail": null, "source": {"title": "Register of Members' Financial Interests, 11 November 2024: Natasha Irons", "url": "https://publications.parliament.uk/pa/cm/cmregmem/241111/irons_natasha.htm"}}, {"phase": "politics", "start": "2018", "end": "2024", "title": "Councillor", "organisation": "Merton London Borough Council", "detail": "She represented Ravensbury ward from 2018 and Figge’s Marsh ward from 2022.", "source": {"title": "Wikipedia: Natasha Irons (politician)", "url": "https://en.wikipedia.org/wiki/Natasha_Irons_(politician)"}}, {"phase": "politics", "start": "2020", "end": "2024", "title": "Cabinet member for local environment and green spaces", "organisation": "Merton London Borough Council", "detail": "The role was expanded to include climate change in 2022.", "source": {"title": "Wikipedia: Natasha Irons (politician)", "url": "https://en.wikipedia.org/wiki/Natasha_Irons_(politician)"}}]$bt$::jsonb::text));

DO $$ BEGIN
  IF (SELECT count(*) FROM public.mp_biography b JOIN bt_undo u USING (member_id) WHERE md5(b.background_timeline::text) = u.cur_md5) <> 25 THEN
    RAISE EXCEPTION 'a timeline is not the 2026-11-07m value (changed since)';
  END IF;
END $$;

UPDATE public.mp_biography b SET background_timeline = NULL, background_last_checked = NULL
  FROM bt_undo u WHERE b.member_id = u.member_id AND md5(b.background_timeline::text) = u.cur_md5;

DO $$
DECLARE
  changed integer;
  changed_outside integer;
  with_timeline integer;
  entry_total integer;
BEGIN
  SELECT count(*) INTO changed FROM public.mp_biography b JOIN bt_before o USING (member_id) WHERE md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  SELECT count(*) INTO changed_outside FROM public.mp_biography b JOIN bt_before o USING (member_id)
   WHERE b.member_id NOT IN (5084, 5086, 5087, 5088, 5090, 5092, 5093, 5094, 5095, 5096, 5097, 5098, 5100, 5103, 5104, 5106, 5107, 5109, 5110, 5112, 5113, 5115, 5116, 5117, 5119) AND md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  SELECT count(*) INTO with_timeline FROM public.mp_biography WHERE background_timeline IS NOT NULL;
  SELECT sum(jsonb_array_length(background_timeline)) INTO entry_total FROM public.mp_biography WHERE background_timeline IS NOT NULL;
  RAISE NOTICE 'UNDO: rows changed %, outside the 25 %, MPs with a timeline %, entries %', changed, changed_outside, with_timeline, entry_total;
  IF changed <> 25 THEN RAISE EXCEPTION 'expected exactly 25 rows changed, got %', changed; END IF;
  IF changed_outside <> 0 THEN RAISE EXCEPTION '% rows outside the 25 changed', changed_outside; END IF;
  IF with_timeline <> 446 THEN RAISE EXCEPTION 'expected 446 MPs with a timeline, got %', with_timeline; END IF;
  IF entry_total <> 5906 THEN RAISE EXCEPTION 'expected 5906 entries, got %', entry_total; END IF;
END $$;

COMMIT;
